        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if (0 <= nr < h and 0 <= nc < w and
                            (nr, nc) not in seen and grid[nr][nc] == color):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            comps.append((color, comp))

    # Extend from the rightmost point on the bottom edge of each substantial object.
    candidates = []
    for color, comp in comps:
        bottom = max(r for r, c in comp)
        right = max(c for r, c in comp if r == bottom)
        if right < w - 1 and len(comp) >= 3:
            candidates.append((color, bottom, right))

    # Isolated endpoint marks can indicate the ray when they are the furthest
    # non-edge mark in the grid.
    isolated = []
    for color, comp in comps:
        if len(comp) == 1:
            r, c = comp[0]
            if c < w - 1:
                isolated.append((c, color, r))
    if isolated:
        c, color, r = max(isolated)
        if not candidates or c > max(x for _, _, x in candidates):
            candidates.append((color, r, c))

    for color, r, c in candidates:
        for x in range(c + 1, w):
            out[r][x] = 1

    return out
