    bands = []
    for r in active:
        if not bands or r - bands[-1][-1] > 2:
            bands.append([r])
        else:
            bands[-1].append(r)

    for band in bands:
        rightmost = max(c for r in band for c, v in enumerate(grid[r]) if v != bg)
        if rightmost == w - 1:
            continue

        candidates = []
        for r in band:
            cols = [c for c, v in enumerate(grid[r]) if v != bg]
            if cols and max(cols) == rightmost:
                run = 0
                c = rightmost
                while c >= 0 and grid[r][c] != bg:
                    run += 1
                    c -= 1
                candidates.append((run, r))

        if candidates:
            best = max(run for run, _ in candidates)
            for run, r in candidates:
                if run == best:
                    for c in range(rightmost + 1, w):
                        out[r][c] = 1

    return out
